<?php

declare(strict_types=1);

namespace Stratum\PMMP;

use pocketmine\block\Block;
use pocketmine\world\ChunkManager;
use pocketmine\world\format\Chunk;
use pocketmine\world\format\PalettedBlockArray;
use pocketmine\world\format\SubChunk;
use pocketmine\world\generator\Generator;

/**
 * Vanilla Java Edition terrain, generated by Stratum's C++ engine.
 *
 * Constructed once per generation worker thread with nothing but the world
 * seed and its options string — again whenever PocketMine-MP restarts a
 * worker it shut down while idle. Opening the world is cheap here: the main
 * thread already opened and compiled it when the world loaded, and pinned
 * it (StratumWorlds), so this is handed that state without the blob being
 * read; unpinned, it is read and compiled once, and the engine shares one
 * compiled dimension across every worker that opens the same blob, noise
 * settings, biome source and seed.
 *
 * What generateChunk() does per chunk is deliberately small — the engine
 * returns sub-chunks already packed the way PalettedBlockArray::fromData
 * reads them, so the only PHP work is translating each sub-chunk's handful
 * of palette entries. There is no per-block PHP.
 */
final class StratumGenerator extends Generator{

	private \Stratum\Dimension $dimension;

	private BlockStateTranslator $translator;

	/**
	 * Every refusal this could make was already made on the main thread,
	 * where PocketMine-MP validated the options as the world loaded
	 * (GeneratorOptions::validate): an exception here, on a worker, takes
	 * the server down rather than failing the world.
	 *
	 * @throws \Stratum\GenerationException if the frozen pipeline cannot be
	 * opened or does not carry this dimension — for a world that is not
	 * pinned, whose blob changed after it loaded.
	 */
	public function __construct(int $seed, string $preset){
		parent::__construct($seed, $preset);

		// The string alone: the blob is not touched here, and a pinned
		// world's generator never reads it.
		$options = GeneratorOptions::parse($preset);
		$this->dimension = \Stratum\Dimension::open(
			$options->blobPath,
			$options->noiseSettings,
			$options->biomeSource,
			$seed
		);
		$this->translator = new BlockStateTranslator();
	}

	public function generateChunk(ChunkManager $world, int $chunkX, int $chunkZ) : void{
		$world->setChunk($chunkX, $chunkZ, $this->assemble($this->encode($chunkX, $chunkZ)));
	}

	/**
	 * generateChunk()'s engine half: the chunk generated and packed in C++,
	 * as Dimension::encodeChunk() hands it to PHP, its fluid updates left
	 * in the world's outbox.
	 *
	 * @internal Public, and apart from assemble(), only so that
	 * tools/pmmp-task-cost can time each half of a generation task on its
	 * own (ext/pocketmine/src/TimedGenerator.php); generateChunk() is the
	 * only caller in the plugin. A method boundary, not a hook: nothing is
	 * tested or recorded here, and the price is one PHP call per chunk.
	 *
	 * @return array<int, array{blocks: array{int, string, list<int>}|null, biomes: array{int, string, list<int>}}>
	 */
	public function encode(int $chunkX, int $chunkZ) : array{
		return $this->dimension->encodeChunk($chunkX, $chunkZ);
	}

	/**
	 * generateChunk()'s PHP half: encode()'s sub-chunks as PocketMine-MP's
	 * own Chunk, each palette entry translated to a PocketMine-MP state id.
	 *
	 * @internal Public only for tools/pmmp-task-cost, as encode() is.
	 *
	 * @param array<int, array{blocks: array{int, string, list<int>}|null, biomes: array{int, string, list<int>}}> $encoded
	 */
	public function assemble(array $encoded) : Chunk{
		$subChunks = [];
		foreach($encoded as $subChunkY => $layers){
			$blockLayers = [];
			if($layers["blocks"] !== null){
				[$bitsPerBlock, $wordArray, $javaPalette] = $layers["blocks"];
				$palette = [];
				foreach($javaPalette as $javaStateId){
					// A few entries per sub-chunk, cached across the whole
					// world after the first chunk.
					$palette[] = $this->translator->translate($javaStateId);
				}
				$blockLayers[] = PalettedBlockArray::fromData($bitsPerBlock, $wordArray, $palette);
			}
			// An all-air sub-chunk keeps an empty layer list, which is how
			// PocketMine-MP's own generators represent one.

			// Biomes are Bedrock's own numeric ids, which is what
			// PocketMine-MP stores; no translation step.
			[$biomeBits, $biomeWords, $biomePalette] = $layers["biomes"];

			// Keys are signed sub-chunk indices (-4..19) and Chunk's
			// constructor indexes by exactly that. A 0-based array would
			// build a world shifted vertically, with nothing to say so.
			$subChunks[$subChunkY] = new SubChunk(
				Block::EMPTY_STATE_ID,
				$blockLayers,
				PalettedBlockArray::fromData($biomeBits, $biomeWords, $biomePalette)
			);
		}

		// All 24 sub-chunks are present, whatever the dimension's height:
		// a key Chunk's constructor does not find becomes air AND an
		// all-ocean biome array, which would be a visibly wrong world with
		// no error. encodeChunk returns every one — for the End, whose
		// terrain is y 0..127, the rest as air with the End's own biomes.
		return new Chunk($subChunks, terrainPopulated: false);
	}

	public function populateChunk(ChunkManager $world, int $chunkX, int $chunkZ) : void{
		// Nothing: features, structures and decoration are M6 (SPEC section
		// 10) and out of scope for v1. Terrain, surface and aquifers are
		// already in what generateChunk placed.
		//
		// PocketMine-MP marks the chunk populated itself, in
		// PopulationUtils::populateChunkWithAdjacents.
	}
}
